-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "Recomendada"
L["rm.mop.deathknight.blood.Description"] = "Recomendada para tanques de Sangue, escolhida na especialização Sangue. Puxa à distância com Eclosão, Toque Gélido ou Garra da Morte. Golpe da Morte abaixo de metade da vida, sempre que Escudo de Sangue estiver ausente (a partir do nível 80) e antes que as quatro runas de Gelo e Profanas fiquem cheias; Golpe Rúnico perto de 90 de poder rúnico (Espiral da Morte com 80 antes de aprendê-lo); Eclosão, senão Toque Gélido e Golpe da Peste, para as doenças, e Sangue Fervente para renová-las a partir do nível 68; Ceifador de Almas abaixo de 35%; Golpe no Coração (Golpe Sangrento antes do nível 60) com duas runas de Sangue; Flagelo Vermelho em Morte e Decomposição enquanto as doenças durarem, senão Sangue Fervente; Transfusão de Sangue com onze cargas; depois Golpe da Morte, Golpe no Coração, Golpe Rúnico e Berrante do Inverno. Três inimigos em você: Morte e Decomposição, um espalhamento de doenças (Sangue Fervente com Sangue Enervante, senão Pestilência) e Sangue Fervente. Lembretes: Presença Sanguínea quando você não tiver nenhuma, Escudo Ósseo, Berrante do Inverno, Congelar Mente, Transfusão Rúnica, Sangue Vampírico, Fortitude Congélida, Energizar Arma Rúnica e Pacto da Morte conforme sua vida, Arma Rúnica Dançante em elites, Exército dos Mortos antes de um chefe em grupo. Ela não consegue ver o dano que está chegando, então Carapaça Antimagia (desativada) e as grandes defesas ficam com você."
L["rm.mop.deathknight.blood.simulator.Name"] = "Reativa à vida (simulador)"
L["rm.mop.deathknight.blood.simulator.Description"] = "Uma alternativa à rotação integrada recomendada de Sangue para tanques de raide com curadores, desativada por padrão: ative esta e desative aquela, ou aumente a prioridade desta. Golpe da Morte só abaixo de 70% de vida, quando Escudo de Sangue estiver ausente ou prestes a expirar, ou antes que as runas de Gelo e Profanas cheguem ao limite, em vez de a cada runa; uma runa de Sangue solitária vai para Golpe no Coração quando faltar mais de um segundo para as runas de Gelo e Profanas. Ela não tem seção de dano em área, e tem os mesmos lembretes da recomendada."
L["rm.mop.deathknight.frost.Name"] = "Arma de duas mãos"
L["rm.mop.deathknight.frost.Description"] = "Gelo com uma arma de duas mãos, a configuração usual para evoluir de nível; escolhida na especialização Gelo sempre que a rotação integrada de duas armas não se aplica. A mesma abertura, doenças, sobrevivência e dano em área da rotação integrada de duas armas, depois Obliterar com Máquina Assassina, Golpe Gélido acima de 76 de poder rúnico, Impacto Uivante com Geada, Obliterar sempre que um par de runas estiver cheio, Obliterar, Impacto Uivante, Sugar Peste, Golpe Gélido com 40 e Berrante do Inverno. Antes de Obliterar (nível 58), Golpe da Morte gasta suas runas Profanas. Os mesmos lembretes da rotação integrada de duas armas."
L["rm.mop.deathknight.frost.dualwield.Name"] = "Duas armas"
L["rm.mop.deathknight.frost.dualwield.Description"] = "Recomendada para Gelo com duas armas de uma mão (Masterfrost); escolhida na especialização Gelo enquanto sua mão secundária segura uma arma. Puxa com Eclosão ou Impacto Uivante (Garra da Morte quando solo). Golpe da Morte com Socorro Negro ou abaixo de 35% de vida, Transfusão de Sangue com onze cargas, doenças (Devastação Profana, Eclosão, Impacto Uivante, Golpe da Peste), Ceifador de Almas abaixo de 35%, Golpe Gélido com Máquina Assassina ou acima de 89 de poder rúnico, Impacto Uivante com Geada ou com as duas runas de Gelo ou as duas runas da Morte prontas, Obliterar com duas runas Profanas abaixo de 77 de poder rúnico, Golpe Gélido acima de 76, Obliterar, Impacto Uivante, Sugar Peste antes que as doenças expirem com Eclosão pronta, Golpe Gélido com 40, Berrante do Inverno. Três inimigos em você: um espalhamento de doenças, Morte e Decomposição e Impacto Uivante. Lembretes: Presença Gélida, Pilar de Gelo, Reviver Morto, Energizar Arma Rúnica com todas as runas indisponíveis, Berrante do Inverno, Congelar Mente, Fortitude Congélida e Pacto da Morte com pouca vida, Exército dos Mortos antes de um chefe em grupo."
L["rm.mop.deathknight.unholy.Name"] = "Profana"
L["rm.mop.deathknight.unholy.Description"] = "Recomendada para Profano, e a rotação integrada para qualquer Cavaleiro da Morte que Sangue e Gelo não reivindiquem, inclusive um sem especialização. Puxa à distância com Eclosão ou Toque Gélido (Garra da Morte quando solo). Golpe da Morte com Socorro Negro ou abaixo de 35% de vida, doenças (Devastação Profana, Eclosão, Golpe da Peste, Toque Gélido), Transfusão de Sangue com onze cargas, Ceifador de Almas abaixo de 35%, Transformação Negra com cinco acúmulos de Infusão Sombria, Espiral da Morte perto do limite de poder rúnico, Morte e Decomposição em um alvo que vá sobreviver, Golpe do Flagelo, Espiral da Morte com Ruína Súbita ou com 40, Eclosão enquanto Força Profana estiver ativa, Ataque Supurante (Golpe Sangrento antes de aprendê-lo), Sugar Peste, Berrante do Inverno. Três inimigos em você: um espalhamento de doenças, Morte e Decomposição, Sangue Fervente e Toque Gélido com uma runa de Gelo. Lembretes: Presença Profana, seu carniçal, Evocar Gárgula sob Sede de Sangue ou em uma luta longa contra elite, Frenesi Profano, Energizar Arma Rúnica, Berrante do Inverno, Congelar Mente, Fortitude Congélida e Pacto da Morte com pouca vida, Exército dos Mortos antes de um chefe em grupo; Carapaça Antimagia vem desativada."
L["rm.mop.deathknight.unholy.simulator.Name"] = "Profano, acúmulo até o limite de runas (simulador)"
L["rm.mop.deathknight.unholy.simulator.Description"] = "Uma alternativa à rotação integrada recomendada de Profano, como o simulador, wowtbc.gg, Method e MaxDps a jogam; desativada por padrão: ative esta e desative aquela, ou aumente a prioridade desta. Enquanto Transformação Negra estiver inativa, Espiral da Morte serve para reconstruir Infusão Sombria, Golpe do Flagelo vem primeiro quando as duas runas Profanas ou as duas runas da Morte estiverem prontas, e Ataque Supurante primeiro quando as duas runas de Sangue e as duas de Gelo estiverem; nos demais casos, a mesma abertura, doenças, dano em área e lembretes da recomendada."
L["rm.retail.deathknight.blood.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.deathknight.blood.Description"] = "Recomendada para Sangue. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Sangue Vampírico e Reviver Morto em combate, Congelar Mente em um lançamento interrompível, e Fortitude Congélida e sua habilidade racial sempre que estiverem prontas em combate. Lançamentos inimigos ficam ocultos em combate, então Congelar Mente só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Fortitude Congélida é com você. O momento da mitigação ativa, Carapaça Antimagia, provocações e berloques ficam com você."
L["rm.retail.deathknight.blood.guide.Name"] = "Referência (Icy Veins e Wowhead)"
L["rm.retail.deathknight.blood.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Sangue dos guias. Em combate no Midnight, seus bônus e as penalidades do alvo ficam ocultos para addons, então os passos que os leem aguardam lá; leia-a ou duplique-a para experimentar. A vida e o poder rúnico ficam ocultos no Retail, então Golpe da Morte é usado sempre que você puder pagar por ele. Puxa com Afago da Morte. Golpe da Morte; Talho Medular (Afago da Morte fora do corpo a corpo) quando Escudo Ósseo estiver ausente, abaixo de cinco cargas, prestes a expirar ou com Exterminar ativo; durante Dádiva dos San'layn, Golpe da Morte, um Sangue Fervente, Morte e Decomposição com Flagelo Vermelho e Golpe no Coração; Morte e Decomposição com Flagelo Vermelho ou contra quatro inimigos; Golpe Vampírico; Consumição; Sangue Fervente com Ponto de Ebulição, com Peste Sanguínea ausente ou com cargas cheias; Golpe no Coração. Lembretes: Reviver Morto, Sangue Vampírico, Marca do Ceifeiro, Arma Rúnica Dançante depois de Marca do Ceifeiro, além dos lembretes utilitários da rotação integrada do Assistente de Combate."
L["rm.retail.deathknight.blood.simc.Name"] = "Referência de Mortífero (SimulationCraft)"
L["rm.retail.deathknight.blood.simc.Description"] = "Apenas referência, desativada por padrão: a lista Mortífero do SimulationCraft, que gasta poder rúnico em Golpe da Morte para causar dano. Os dados de combate ocultos a impedem de funcionar em combate no Midnight, e o poder rúnico fica oculto no Retail, então não há descarga no limite. Morte e Decomposição sempre que não estiver ativa, Marca do Ceifeiro, Talho Medular com Exterminar, Afago da Morte para Escudo Ósseo quando faltam runas (senão Talho Medular), Golpe da Morte, Sangue Fervente, Consumição fora de Arma Rúnica Dançante, Golpe no Coração. Lembretes: Reviver Morto, Arma Rúnica Dançante, Sangue Vampírico e os lembretes utilitários."
L["rm.retail.deathknight.frost.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.deathknight.frost.Description"] = "Recomendada para Gélido. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Sopro de Sindragosa e Reviver Morto em combate, Congelar Mente em um lançamento interrompível, e Fortitude Congélida e sua habilidade racial sempre que estiverem prontas em combate. Lançamentos inimigos ficam ocultos em combate, então Congelar Mente só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Fortitude Congélida é com você."
L["rm.retail.deathknight.frost.guide.Name"] = "Referência (Icy Veins e SimulationCraft)"
L["rm.retail.deathknight.frost.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Gélido dos guias. Máquina Assassina, Geada e Gelâmina ficam ocultas em combate no Midnight, então ela não pode funcionar lá; o poder rúnico fica oculto no Retail, então não há verificação de limite. Obliterar com duas Máquinas Assassinas ou uma com três runas, Golpe Gélido em cinco acúmulos de Gelâmina com Lâmina Devastadora, Impacto Uivante com Geada, Obliterar com Máquina Assassina, Golpe Gélido, Obliterar; contra três ou mais inimigos entram Foice Gélida e Avanço Glacial; Impacto Uivante fora do corpo a corpo. Lembretes: Inverno Impiedoso, Pilar de Gelo, Sopro de Sindragosa e Fúria da Serpe Gélida durante Pilar, Marca do Ceifeiro, Reviver Morto, Energizar Arma Rúnica com duas cargas, além dos lembretes utilitários."
L["rm.retail.deathknight.frost.wowhead.Name"] = "Referência (Wowhead)"
L["rm.retail.deathknight.frost.wowhead.Description"] = "Apenas referência, desativada por padrão: a ordem de Gélido da Wowhead, que coloca os tempos de recarga na rotação. Os dados de combate ocultos a impedem de funcionar em combate no Midnight; o poder rúnico fica oculto no Retail, então não há verificação de limite. Energizar Arma Rúnica com duas cargas, Marca do Ceifeiro, Pilar de Gelo, Sopro de Sindragosa, Fúria da Serpe Gélida; depois Obliterar com duas Máquinas Assassinas ou uma com Exterminar, Impacto Uivante com Geada, Obliterar com Máquina Assassina, Energizar Arma Rúnica para obter uma nova, Golpe Gélido, Obliterar, Impacto Uivante. Contra três ou mais inimigos entram Foice Gélida e Avanço Glacial."
L["rm.retail.deathknight.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.deathknight.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Cavaleiro da Morte). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Cavaleiro da Morte compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.deathknight.unholy.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.deathknight.unholy.Description"] = "Recomendada para Profano. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight (ele invoca seu carniçal e usa Exército dos Mortos e Transformação Negra por conta própria); aguarda enquanto você lança ou canaliza. Junto a isso: Congelar Mente em um lançamento interrompível, e Fortitude Congélida e sua habilidade racial sempre que estiverem prontas em combate. Lançamentos inimigos ficam ocultos em combate, então Congelar Mente só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Fortitude Congélida é com você."
L["rm.retail.deathknight.unholy.guide.Name"] = "Referência (Icy Veins e Wowhead)"
L["rm.retail.deathknight.unholy.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Profano dos guias. Ativações e pestes ficam ocultas em combate no Midnight, então ela não pode funcionar lá; o poder rúnico e a vida do alvo ficam ocultos no Retail, então a janela de execução e o gasto de poder rúnico dos San'layn ficam de fora. Reviver Morto sem carniçal; Foice Purulenta para manter ativa a aceleração da sua peste; Ceifador de Almas com Ceifadora; Putrefazer durante Transformação Negra; Espiral da Morte (Epidemia contra quatro ou mais inimigos) com Ruína Súbita ou Conhecimento Proibido; Ataque Supurante sem cargas de Carniçal Menor, Golpe do Flagelo com elas; Espiral da Morte. Lembretes: Exército dos Mortos, Transformação Negra, Eclosão quando suas pestes estiverem ausentes, além dos lembretes utilitários."
L["rm.retail.deathknight.unholy.simc.Name"] = "Referência (SimulationCraft)"
L["rm.retail.deathknight.unholy.simc.Description"] = "Apenas referência, desativada por padrão: a lista de Profano do SimulationCraft, que gasta Espiral da Morte com muito mais frequência. Os dados de combate ocultos a impedem de funcionar em combate no Midnight; o poder rúnico e a vida do alvo ficam ocultos no Retail, então as verificações de limite e de execução ficam de fora. Manutenção de Foice Purulenta, Ceifador de Almas durante Transformação Negra, Espiral da Morte com Ruína Súbita, Putrefazer durante Transformação Negra, Espiral da Morte durante Transformação Negra ou Conhecimento Proibido e sempre que Exército dos Mortos estiver a mais de 5 segundos de ficar pronto, Golpe do Flagelo com cargas de Carniçal Menor, Ataque Supurante. Contra três ou mais inimigos: Epidemia no lugar de Espiral da Morte e Ataque Supurante abaixo de três cargas. Lembretes: Eclosão, Morte e Decomposição em grupos de inimigos, Exército dos Mortos, Transformação Negra."
